parameters.jsCode:
const response = $input.first().json.output ?? $input.first().json.text ?? "";

const cleaned = response
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let scores;

try {
  scores = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Invalid JSON returned by Quality Checker Agent.\n${error.message}`);
}

return scores;
